import Foundation

// Input is the report replay of an existing captured workout. No repetitions,
// dates, loads, heart rate, or energy values are generated by this verification.
@main enum VerifyWholePhoneReport {
    @MainActor static func main() throws {
        guard (2...3).contains(CommandLine.arguments.count) else { throw CocoaError(.fileNoSuchFile) }
        let sourceURL = URL(fileURLWithPath: CommandLine.arguments[1])
        let original = try Data(contentsOf: sourceURL)
        let records = try JSONDecoder().decode([WorkoutSync.Record].self, from: original)
        guard let source = records.first, let report = source.workoutReport,
              report.sets.count == 1, report.totalReps > 1 else { throw CocoaError(.fileReadCorruptFile) }
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("PowerReps.WholeReportCheck." + UUID().uuidString)
        let suite = "PowerReps.WholeReportCheck." + UUID().uuidString
        let defaults = UserDefaults(suiteName: suite)!
        defer { defaults.removePersistentDomain(forName: suite); try? FileManager.default.removeItem(at: root) }
        func store(_ name: String) -> PhoneWorkoutStore {
            PhoneWorkoutStore(defaults: defaults, reminderID: suite,
                              watchArchiveURL: root.appendingPathComponent(name + "/watch.json"),
                              snapshotURL: root.appendingPathComponent(name + "/records-v3.json"))
        }
        let primary = store("primary")
        try primary.acceptWatchHistory(records)
        precondition(primary.history.count == records.count)
        let item = primary.history.first { $0.id == source.id }!
        precondition(item.sourceWorkoutReport == report && item.totalReps == report.totalReps)
        precondition(item.activeDuration == report.activeDuration)
        precondition(item.repetitions(for: .squat) == report.totalReps)
        if CommandLine.arguments.count == 3 {
            let destination = URL(fileURLWithPath: CommandLine.arguments[2])
            try FileManager.default.createDirectory(at: destination.deletingLastPathComponent(), withIntermediateDirectories: true)
            try Data(contentsOf: primary.snapshotURL).write(to: destination, options: .atomic)
        }
        if !report.hasKnownWeights {
            precondition(!item.hasKnownWeight && item.volume == nil && item.measuredSets.isEmpty)
            let insights = RecordTrainingInsights(records: primary.history, filter: RecordFilter(), now: Date())
            precondition(insights.maximumWeightBreakdown.isEmpty && insights.weightBreakdown.isEmpty && insights.totalKnownVolume == nil)
            let csv = primary.csv(records: primary.history, sets: true)
            precondition(!csv.contains("\"0.0\""), "Unknown sensor-capture load was invented as measured zero")
        }
        let ids = report.sets.flatMap(\.repetitions).map(\.id)
        let split = [Array(ids.prefix(1)), Array(ids.dropFirst(1))]
        precondition(primary.updateReportGrouping(id: source.id, groups: split))
        precondition(primary.history[0].workoutReport?.sets.count == 2)
        precondition(primary.history[0].sourceWorkoutReport == report)
        let reopened = store("primary")
        precondition(reopened.history[0].reportGrouping == split)
        try reopened.acceptWatchHistory(records)
        precondition(reopened.history[0].reportGrouping == split && reopened.history[0].sourceWorkoutReport == report)

        let backup = try reopened.backupData()
        let versioned = try JSONDecoder().decode(RecordBackup.self, from: backup)
        precondition(versioned.version == 4 && versioned.snapshot.version == 4)
        let restored = store("restored")
        let preview = try restored.previewRestore(backup)
        precondition(preview.added == records.count)
        try restored.restore(preview)
        precondition(restored.history[0].reportGrouping == split && restored.history[0].sourceWorkoutReport == report)
        let repeatedPreview = try restored.previewRestore(backup)
        precondition(repeatedPreview.added == 0)
        var corrupt = try JSONDecoder().decode(RecordBackup.self, from: backup)
        corrupt.snapshot.history[0].reportGrouping = [ids + [ids[0]]]
        do { _ = try restored.previewRestore(JSONEncoder().encode(corrupt)); preconditionFailure("Duplicate grouping accepted") }
        catch { }
        precondition(restored.history[0].reportGrouping == split)
        precondition(!restored.updateReportGrouping(id: source.id, groups: [Array(ids.dropFirst())]))
        precondition(restored.history[0].reportGrouping == split)
        precondition(restored.updateReportGrouping(id: source.id, groups: nil))
        precondition(restored.history[0].workoutReport == report)

        precondition(restored.updateRecord(id: source.id, date: source.date, sets: [], duration: nil,
                                          summaryReps: source.totalReps + 1, summaryWeight: source.maxWeight))
        try restored.acceptWatchHistory(records)
        let corrected = restored.history[0]
        precondition(corrected.totalReps == source.totalReps + 1 && corrected.sourceWorkoutReport == report)
        precondition(!corrected.reportMatchesCorrection && corrected.activeDuration == nil)
        precondition(!RecordFilter(exercise: .squat).includes(corrected))
        precondition(restored.deleteRecords(ids: [source.id]))
        try restored.acceptWatchHistory(records)
        precondition(restored.history.isEmpty)
        let migrationFolder = root.appendingPathComponent("migration")
        try FileManager.default.createDirectory(at: migrationFolder, withIntermediateDirectories: true)
        var legacy = RecordSnapshot()
        legacy.version = 3
        let legacyData = try JSONEncoder().encode(legacy)
        try legacyData.write(to: migrationFolder.appendingPathComponent("records-v3.json"))
        let migrated = store("migration")
        precondition(!migrated.requiresRecovery)
        let migratedSnapshot = try JSONDecoder().decode(RecordSnapshot.self, from: Data(contentsOf: migrated.snapshotURL))
        precondition(migratedSnapshot.version == 4)
        let preserved = try Data(contentsOf: migrationFolder.appendingPathComponent("before-schema4.json"))
        precondition(preserved == legacyData)
        let after = try Data(contentsOf: sourceURL)
        precondition(after == original)
        let result: [String: Any] = ["sourceRecords": records.count, "actualRepetitions": report.totalReps,
                                   "sourceReportPreserved": true, "groupingRestartSyncBackupRoundTrip": true,
                                   "malformedGroupingRejected": true, "globalCorrectionPreserved": true,
                                   "deletionDoesNotReappear": true, "unknownLoadNotInvented": !report.hasKnownWeights,
                                   "sourceFileUnchanged": true, "backupVersion": 4, "snapshotVersion": 4, "previousSchemaPreserved": true]
        print(String(data: try JSONSerialization.data(withJSONObject: result, options: [.prettyPrinted, .sortedKeys]), encoding: .utf8)!)
    }
}
